{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        mut = max(core[u], core[v], d)
        edges.append((mut, u, v))
    edges.sort()
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0
    for mut, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mut])
            total_weight += mut
        if len(mst_edges) == n - 1:
            break
    if len(mst_edges) != n-1:
        raise ValueError("Graph not connected")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
